from fractions import Fraction
from typing import Sequence

def product(factors: Sequence[Sequence[int]], degree: int) -> tuple[int, list[Fraction]]:
    p = [Fraction(1)] + [Fraction(0)] * degree
    for factor in factors:
        if not factor or factor[0] != 1:
            raise ValueError("normalization requires constant coefficient 1")
        p = [sum((p[i] * Fraction(factor[k-i]) for i in range(k+1)
                  if i < len(p) and k-i < len(factor)), Fraction(0))
             for k in range(degree+1)]
    return -len(factors), p

if __name__ == "__main__":
    print(product([[1,1], [1,2], [1,-1,1]], 4))

from fractions import Fraction
from typing import Sequence

def solve(a: Sequence[Sequence[int]], b: Sequence[int]) -> list[Fraction]:
    n = len(a)
    m = [[Fraction(x) for x in a[i]] + [Fraction(b[i])] for i in range(n)]
    for c in range(n):
        pivot = next((r for r in range(c,n) if m[r][c]), None)
        if pivot is None: raise ValueError("noninjective encoding")
        m[c], m[pivot] = m[pivot], m[c]
        d=m[c][c]; m[c]=[x/d for x in m[c]]
        for r in range(n):
            if r != c:
                d=m[r][c]; m[r]=[x-d*y for x,y in zip(m[r],m[c])]
    return [m[i][-1] for i in range(n)]

if __name__ == "__main__":
    print(solve([[1,1],[1,-1]], [5,1]))

from typing import Sequence

def observe(rows: Sequence[Sequence[int]], vector: Sequence[int]) -> list[int]:
    return [sum(x*y for x,y in zip(row,vector)) for row in rows]

def collision() -> tuple[list[int], list[int], list[int]]:
    rows=[[1,1]]; u=[3,2]; v=[4,1]
    assert u != v and observe(rows,u) == observe(rows,v)
    return u, v, observe(rows,u)

if __name__ == "__main__": print(collision())

